#!/usr/bin/env python3
"""Execute the actual submitted CLI. Only public examples are used."""
from contextlib import contextmanager
import ctypes
import errno
import json
import os
from pathlib import Path
import resource
import selectors
import signal
import stat
import subprocess
import sys
import tempfile
import time

from public_sanity import check_response, strict_loads

HERE = Path(__file__).resolve().parent
CHILD_WALL_SECONDS = 180.0
CLEANUP_WALL_SECONDS = 5.0
INTERRUPT_SIGNALS = {signal.SIGINT, signal.SIGTERM}


class CheckerInterrupted(BaseException):
    def __init__(self, signum):
        self.signum = signum


@contextmanager
def interruption_guard():
    def interrupted(signum, frame):
        raise CheckerInterrupted(signum)
    previous = {sig: signal.getsignal(sig) for sig in INTERRUPT_SIGNALS}
    try:
        for sig in INTERRUPT_SIGNALS:
            signal.signal(sig, interrupted)
        yield
    finally:
        for sig, handler in previous.items():
            signal.signal(sig, handler)


@contextmanager
def blocked_interruptions():
    previous = signal.pthread_sigmask(signal.SIG_BLOCK, INTERRUPT_SIGNALS)
    try:
        yield previous
    finally:
        signal.pthread_sigmask(signal.SIG_SETMASK, previous)


def prctl(option, arg2=0, arg3=0):
    libc = ctypes.CDLL(None, use_errno=True)
    call = libc.prctl
    call.argtypes = [ctypes.c_int, ctypes.c_ulong, ctypes.c_ulong,
                     ctypes.c_ulong, ctypes.c_ulong]
    call.restype = ctypes.c_int
    if call(option, arg2, arg3, 0, 0) != 0:
        error = ctypes.get_errno()
        raise OSError(error, os.strerror(error))


def child_setup(previous_mask):
    """Restore scored exclusions after Popen has created the child session."""
    limits()
    class Filter(ctypes.Structure):
        _fields_ = [("code", ctypes.c_ushort), ("jt", ctypes.c_ubyte),
                    ("jf", ctypes.c_ubyte), ("value", ctypes.c_uint32)]
    class Program(ctypes.Structure):
        _fields_ = [("length", ctypes.c_ushort),
                    ("filters", ctypes.POINTER(Filter))]
    # Linux x86_64 seccomp_data arch/nr offsets and syscall numbers. The
    # supervisor needs these five calls; submitted descendants must not use
    # them to leave their session/group or signal the supervisor.
    instructions = [
        (0x20, 0, 0, 4), (0x15, 1, 0, 0xc000003e),
        (0x06, 0, 0, 0x80000000), (0x20, 0, 0, 0),
        (0x35, 0, 1, 0x40000000), (0x06, 0, 0, 0x80000000),
    ]
    for number in (62, 200, 234, 112, 109):
        instructions.extend([(0x15, 0, 1, number),
                             (0x06, 0, 0, 0x00050000 | errno.EPERM)])
    instructions.append((0x06, 0, 0, 0x7fff0000))
    filters = (Filter * len(instructions))(*(Filter(*i) for i in instructions))
    program = Program(len(filters), filters)
    prctl(38, 1)  # PR_SET_NO_NEW_PRIVS
    prctl(22, 2, ctypes.cast(ctypes.pointer(program), ctypes.c_void_p).value)
    for sig in INTERRUPT_SIGNALS:
        signal.signal(sig, signal.SIG_DFL)
    signal.pthread_sigmask(signal.SIG_SETMASK, previous_mask)


def kill_group(pgid):
    try:
        os.killpg(pgid, signal.SIGKILL)
    except ProcessLookupError:
        pass


def cleanup_group(process):
    """Called with interrupts blocked, even after the initial child exits."""
    deadline = time.monotonic() + CLEANUP_WALL_SECONDS
    while True:
        # Repeat to cover a fork already in progress when SIGKILL arrived.
        kill_group(process.pid)
        try:
            pid, status = os.waitpid(-process.pid, os.WNOHANG)
        except ChildProcessError:
            break
        if pid:
            if pid == process.pid:
                process.returncode = os.waitstatus_to_exitcode(status)
            continue
        if time.monotonic() >= deadline:
            raise ValueError("child group cleanup deadline")
        time.sleep(0.01)
    # The checker is a subreaper. With group changes denied in the child,
    # every descendant is adopted here and must be reaped before success.
    try:
        os.killpg(process.pid, 0)
    except ProcessLookupError:
        return
    raise ValueError("child group cleanup incomplete")


def leader_exit(process):
    # Keep the leader's zombie until group cleanup, preserving its PID/PGID
    # even when it exited before its descendants closed inherited pipes.
    status = os.waitid(os.P_PID, process.pid,
                       os.WEXITED | os.WNOHANG | os.WNOWAIT)
    if status is None:
        return None
    return status.si_status if status.si_code == os.CLD_EXITED else -status.si_status


def limits():
    for kind, pair in (
        (resource.RLIMIT_AS, (2*1024**3, 2*1024**3)),
        (resource.RLIMIT_CPU, (180, 181)),
        (resource.RLIMIT_NOFILE, (256, 256)),
        (resource.RLIMIT_NPROC, (64, 64)),
        (resource.RLIMIT_FSIZE, (64*1024**2, 64*1024**2)),
        (resource.RLIMIT_CORE, (0, 0)),
    ):
        resource.setrlimit(kind, pair)


def child_run(path, data):
    if os.geteuid() == 0:
        raise ValueError("refusing submitted code as root")
    with interruption_guard():
        return run_managed_child(path, data)


def run_managed_child(path, data):
    if os.uname().machine != "x86_64" or not hasattr(os, "waitid"):
        raise ValueError("public checker requires Linux x86_64 process supervision")
    prctl(36, 1)  # PR_SET_CHILD_SUBREAPER
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "HOME": "/workspace",
           "LANG": "C", "LC_ALL": "C", "TMPDIR": str(HERE/"tmp"),
           "PYTHONDONTWRITEBYTECODE": "1", "PYTHONUNBUFFERED": "1",
           "PYTHONHASHSEED": "0", "OPENBLAS_NUM_THREADS": "1",
           "OMP_NUM_THREADS": "1", "MKL_NUM_THREADS": "1"}
    process = None
    output = [bytearray(), bytearray()]
    sel, offset = selectors.DefaultSelector(), 0
    streams = []
    deadline = time.monotonic() + CHILD_WALL_SECONDS
    try:
        # No signal may arrive after fork but before process is assigned.
        # The child restores the previous mask after its trusted setup.
        with blocked_interruptions() as previous_mask:
            process = subprocess.Popen(
                [sys.executable, "-I", "-B", str(path)],
                stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                stderr=subprocess.PIPE, cwd=HERE, env=env, close_fds=True,
                start_new_session=True,
                preexec_fn=lambda: child_setup(previous_mask))
            streams = [process.stdin, process.stdout, process.stderr]
        for stream in streams:
            os.set_blocking(stream.fileno(), False)
        if data:
            sel.register(process.stdin, selectors.EVENT_WRITE, -1)
        else:
            process.stdin.close()
        sel.register(process.stdout, selectors.EVENT_READ, 0)
        sel.register(process.stderr, selectors.EVENT_READ, 1)
        code = None
        while sel.get_map() or code is None:
            remaining = deadline-time.monotonic()
            if remaining <= 0:
                raise ValueError("child wall limit")
            if code is None:
                code = leader_exit(process)
                if code is not None:
                    if code != 0:
                        raise ValueError("child exited nonzero: " + str(code))
                    kill_group(process.pid)
            # Closing all descriptors does not end a still-running child.
            if not sel.get_map():
                if code is None:
                    time.sleep(min(0.01, remaining))
                continue
            for key, _ in sel.select(min(0.05, remaining)):
                stream, index = key.fileobj, key.data
                if index == -1:
                    try:
                        offset += os.write(stream.fileno(), memoryview(data)[offset:offset+65536])
                    except BrokenPipeError:
                        offset = len(data)
                    except BlockingIOError:
                        continue
                    if offset == len(data):
                        sel.unregister(stream)
                        stream.close()
                else:
                    cap = (32*1024**2, 1024**2)[index]
                    try:
                        block = os.read(stream.fileno(), min(65536, cap-len(output[index])+1))
                    except BlockingIOError:
                        continue
                    if not block:
                        sel.unregister(stream)
                        stream.close()
                    elif len(output[index])+len(block) > cap:
                        raise ValueError("child output limit")
                    else:
                        output[index].extend(block)
        return bytes(output[0])
    finally:
        # Repeated SIGINT/SIGTERM cannot interrupt descendant cleanup. A
        # pending signal is delivered after cleanup and prevents success.
        with blocked_interruptions():
            try:
                if process is not None:
                    cleanup_group(process)
            finally:
                sel.close()
                for stream in streams:
                    stream.close()


def main():
    if os.geteuid()==0:
        raise ValueError("refusing candidate/build code as root")
    import shutil,runpy
    (HERE/"tmp").mkdir(exist_ok=True)
    folder=Path(tempfile.mkdtemp(prefix="public-native-",dir=HERE/"tmp"))
    try:
        build_module=runpy.run_path(str(HERE/"build.py"),run_name="public_build_helpers")
        frozen=folder/"src";build_module["collect"](HERE/"src",frozen)
        binary=folder/"scamptrie"
        boot=folder/"build-entry.py"
        boot.write_text("import sys,runpy\nsys.argv=["+repr(str(HERE/"build.py"))+",'--source',"+repr(str(frozen))+",'--output',"+repr(str(binary))+"]\nrunpy.run_path("+repr(str(HERE/"build.py"))+",run_name='__main__')\n")
        child_run(boot,b"")
        if not binary.is_file()or binary.is_symlink():raise ValueError("compiled program missing")
        entry=folder/"run-entry.py"
        entry.write_text("import os,runpy\nos.environ['SCAMP_BINARY']="+repr(str(binary))+"\nrunpy.run_path("+repr(str(HERE/"run.py"))+",run_name='__main__')\n")
        fixtures=json.loads((HERE/"examples/checks.json").read_text())
        for fixture in fixtures:
            response=strict_loads(child_run(entry,fixture["input"].encode('utf-8')))
            check_response(fixture,response)
            print("PASS",fixture["name"],flush=True)
    finally:
        with blocked_interruptions():shutil.rmtree(folder)
    print("Public examples passed; this is not hidden acceptance.")


if __name__=="__main__":
    try:
        with interruption_guard():main()
    except CheckerInterrupted as exc:
        print("FAIL: checker interrupted by signal",exc.signum,file=sys.stderr);sys.exit(128+exc.signum)
    except (AssertionError,ValueError,OSError,subprocess.SubprocessError,UnicodeError)as exc:
        print("FAIL:",str(exc)or type(exc).__name__,file=sys.stderr);sys.exit(1)
